macro_rules! deps {
    () => {
        TryInitError!();
    };
}

macro_rules! SubscriberInitExt {
    () => {
        deps!();
        # [doc = " Extension trait adding utility methods for subscriber initialization."] # [doc = ""] # [doc = " This trait provides extension methods to make configuring and setting a"] # [doc = " [default subscriber] more ergonomic. It is automatically implemented for all"] # [doc = " types that can be converted into a [trace dispatcher]. Since `Dispatch`"] # [doc = " implements `From<T>` for all `T: Subscriber`, all `Subscriber`"] # [doc = " implementations will implement this extension trait as well. Types which"] # [doc = " can be converted into `Subscriber`s, such as builders that construct a"] # [doc = " `Subscriber`, may implement `Into<Dispatch>`, and will also receive an"] # [doc = " implementation of this trait."] # [doc = ""] # [doc = " [default subscriber]: https://docs.rs/tracing/0.1.21/tracing/dispatcher/index.html#setting-the-default-subscriber"] # [doc = " [trace dispatcher]: https://docs.rs/tracing/0.1.21/tracing/dispatcher/index.html"] pub trait SubscriberInitExt where Self : Into < Dispatch > , { # [doc = " Sets `self` as the [default subscriber] in the current scope, returning a"] # [doc = " guard that will unset it when dropped."] # [doc = ""] # [doc = " If the \"tracing-log\" feature flag is enabled, this will also initialize"] # [doc = " a [`log`] compatibility layer. This allows the subscriber to consume"] # [doc = " `log::Record`s as though they were `tracing` `Event`s."] # [doc = ""] # [doc = " [default subscriber]: https://docs.rs/tracing/0.1.21/tracing/dispatcher/index.html#setting-the-default-subscriber"] # [doc = " [`log`]: https://crates.io/log"] # [cfg (feature = "std")] # [cfg_attr (docsrs , doc (cfg (feature = "std")))] fn set_default (self) -> dispatcher :: DefaultGuard { # [cfg (feature = "tracing-log")] let _ = tracing_log :: LogTracer :: init () ; dispatcher :: set_default (& self . into ()) } # [doc = " Attempts to set `self` as the [global default subscriber] in the current"] # [doc = " scope, returning an error if one is already set."] # [doc = ""] # [doc = " If the \"tracing-log\" feature flag is enabled, this will also attempt to"] # [doc = " initialize a [`log`] compatibility layer. This allows the subscriber to"] # [doc = " consume `log::Record`s as though they were `tracing` `Event`s."] # [doc = ""] # [doc = " This method returns an error if a global default subscriber has already"] # [doc = " been set, or if a `log` logger has already been set (when the"] # [doc = " \"tracing-log\" feature is enabled)."] # [doc = ""] # [doc = " [global default subscriber]: https://docs.rs/tracing/0.1.21/tracing/dispatcher/index.html#setting-the-default-subscriber"] # [doc = " [`log`]: https://crates.io/log"] fn try_init (self) -> Result < () , TryInitError > { dispatcher :: set_global_default (self . into ()) . map_err (TryInitError :: new) ? ; # [cfg (feature = "tracing-log")] tracing_log :: LogTracer :: builder () . with_max_level (tracing_core :: LevelFilter :: current () . as_log ()) . init () . map_err (TryInitError :: new) ? ; Ok (()) } # [doc = " Attempts to set `self` as the [global default subscriber] in the current"] # [doc = " scope, panicking if this fails."] # [doc = ""] # [doc = " If the \"tracing-log\" feature flag is enabled, this will also attempt to"] # [doc = " initialize a [`log`] compatibility layer. This allows the subscriber to"] # [doc = " consume `log::Record`s as though they were `tracing` `Event`s."] # [doc = ""] # [doc = " This method panics if a global default subscriber has already been set,"] # [doc = " or if a `log` logger has already been set (when the \"tracing-log\""] # [doc = " feature is enabled)."] # [doc = ""] # [doc = " [global default subscriber]: https://docs.rs/tracing/0.1.21/tracing/dispatcher/index.html#setting-the-default-subscriber"] # [doc = " [`log`]: https://crates.io/log"] fn init (self) { self . try_init () . expect ("failed to set global default subscriber") } }
    };
}

SubscriberInitExt!()